contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        uint cBalBefore = address(c).balance;
        uint userBalBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        require(userBalBefore == 0);

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint userBalAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;

        assert(!reverted && userBalAfter == 0 && cBalAfter == cBalBefore);
    }

    receive() external payable {}
}

