pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint cBalBefore = address(c).balance;
        uint256 userBalBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { userBalBefore = __r; } catch { return; }
        vm.assume(userBalBefore == 0);
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;
        uint256 userBalAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { userBalAfter = __r; } catch { return; }
        assertTrue(!reverted && userBalAfter == 0 && cBalAfter == cBalBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
